sys_script.script:
(function investigationLifecycle() {
    // Only process status changes for lifecycle logic
    if (!current.status.changes()) {
        gs.debug('[Retail Store Assistant] Investigation Lifecycle: no status change for investigation ' + current.getValue('investigation_number'));
        return;
    }

    var oldStatus = previous.getValue('status');
    var newStatus = current.getValue('status');
    var investNumber = current.getValue('investigation_number');

    gs.info('[Retail Store Assistant] Investigation Lifecycle: processing transition "' + oldStatus + '" → "' + newStatus + '" for investigation ' + investNumber);

    // Define valid transitions (V2.8: Open → In Progress → Resolved → Closed)
    var validTransitions = {
        'open': ['in_progress'],
        'in_progress': ['resolved'],
        'resolved': ['closed'],
        'closed': []
    };

    var allowed = validTransitions[oldStatus] || [];
    var isValid = false;
    for (var i = 0; i < allowed.length; i++) {
        if (allowed[i] === newStatus) {
            isValid = true;
            break;
        }
    }

    if (!isValid) {
        gs.error('[Retail Store Assistant] Investigation Lifecycle: REJECTED invalid transition "' + oldStatus + '" → "' + newStatus + '" for investigation ' + investNumber);
        gs.addErrorMessage('Investigation lifecycle violation: cannot transition from "' + oldStatus + '" to "' + newStatus + '".');
        current.setAbortAction(true);
        return;
    }

    var now = new GlideDateTime();

    // Handle transition to In Progress
    if (newStatus === 'in_progress') {
        gs.info('[Retail Store Assistant] Investigation Lifecycle: investigation ' + investNumber + ' moved to In Progress');
    }

    // Handle transition to Resolved: validate resolution is provided
    if (newStatus === 'resolved') {
        var resolution = current.getValue('resolution');
        if (!resolution) {
            gs.error('[Retail Store Assistant] Investigation Lifecycle: cannot resolve investigation ' + investNumber + ' — resolution field is required');
            gs.addErrorMessage('Investigation cannot be resolved: a resolution decision (No Adjustment or Adjustment Required) must be recorded.');
            current.setAbortAction(true);
            return;
        }
        gs.info('[Retail Store Assistant] Investigation Lifecycle: investigation ' + investNumber + ' resolved with resolution="' + resolution + '"');
    }

    // Handle transition to Closed: validate closed_by and closed_on
    if (newStatus === 'closed') {
        // Set closed_on if not already provided
        if (!current.getValue('closed_on')) {
            current.setValue('closed_on', now.getDisplayValue());
        }

        // Set closed_by to current user if not already provided
        if (!current.getValue('closed_by')) {
            current.setValue('closed_by', gs.getUserID());
        }

        // Validate resolution exists (must have been resolved first)
        var resolution = current.getValue('resolution');
        if (!resolution) {
            gs.error('[Retail Store Assistant] Investigation Lifecycle: cannot close investigation ' + investNumber + ' — resolution is missing (must be resolved before closing)');
            gs.addErrorMessage('Investigation cannot be closed: resolution must be recorded before closure.');
            current.setAbortAction(true);
            return;
        }

        gs.info('[Retail Store Assistant] Investigation Lifecycle: investigation ' + investNumber + ' closed by ' + current.getValue('closed_by') + ' at ' + current.getValue('closed_on'));
    }

    // CRITICAL: Do NOT modify Inventory Position
    // CRITICAL: Do NOT create Inventory Transactions
    // CRITICAL: Do NOT bypass Adjustment Request
    // The correction path is: Investigation → Adjustment Request → Approval → Posted Transaction

    gs.info('[Retail Store Assistant] Investigation Lifecycle: investigation ' + investNumber + ' successfully transitioned to "' + newStatus + '"');
})();
